        frame_map = FrameMap(output / 'video_frames.jsonl')
        for name in CAMERAS:
            sinks[name] = LosslessSourceSink(output, name)
        cameras = EndingRoadCameraCapture(world, carla, turning, sinks)
        frames, start = [], None
